local a='builtin.everyone'local b={'command.quit','command.stop','command.start','command.restart','command.ensure','command.refresh','command.exec','command.add_ace','command.remove_ace','command.add_principal','command.remove_principal','command.set','command.sets','command.setr'}Doctor.register({id='permisos',title='Permisos ACE',run=function(c)local d=Config.Permission.ace;if IsPrincipalAceAllowed(a,d)then c:add({severity='error',title=('Cualquier jugador puede usar /%s'):format(Config.Command),where=('server.cfg (%s)'):format(d),why='El permiso está concedido a builtin.everyone, que incluye a todos los que se conectan.',fix={('Busca y borra la línea "add_ace builtin.everyone %s allow" (o una más general).'):format(d),('Concédelo solo a tu grupo de administración: add_ace group.admin %s allow'):format(d)}})else local e=false;for f,g in ipairs(Config.Permission.principals)do if IsPrincipalAceAllowed(g,d)then e=true;break end end;if not e then c:add({severity='advertencia',title=('Ningún grupo configurado tiene permiso para /%s'):format(Config.Command),where='server.cfg',why=('Ni %s tienen "%s". Solo la consola del servidor podrá usar el comando.'):format(table.concat(Config.Permission.principals,', '),d),fix={('Añade a server.cfg: add_ace group.admin %s allow'):format(d),'Si tu grupo de administración tiene otro nombre, cámbialo también en Config.Permission.principals.'}})end end;if IsPrincipalAceAllowed(a,'command')then c:add({severity='error',title='Todos los jugadores pueden usar cualquier comando restringido',where='server.cfg (add_ace builtin.everyone command allow)',why='Cualquiera podría parar recursos, cambiar permisos o apagar el servidor.',fix={'Borra la línea "add_ace builtin.everyone command allow".','Concede "command" solo a tu grupo de administración: add_ace group.admin command allow'}})return end;local h={}for f,i in ipairs(b)do if IsPrincipalAceAllowed(a,i)then h[#h+1]=i:sub(9)end;c:step()end;if#h>0 then c:add({severity='error',title='Hay comandos de administración abiertos a todos los jugadores',where='server.cfg (builtin.everyone)',why=('Cualquier jugador puede usar: %s.'):format(Doctor.nameList(h)),fix={'Borra las líneas "add_ace builtin.everyone command.<nombre> allow" de esos comandos.'}})end end})